Import ListNotations.
Open Scope Z_scope.

Notation UNREG_W :=
  [(XS1_LO, XS1_HI); (XS2_LO, XS2_HI); (XS3_LO, XS3_HI); (0x762a20%Z, 0x762a23%Z); (0x7629c0%Z, 0x7629c2%Z)] (only parsing).

Definition unreg_loop_post (sp gp tp : word) (F : bvmap 5 word) (fc : bv 32) (m : mem) : machine_state -> Prop :=
  fun ms' => exists (ra' s0' t0' t1' t2' a0' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6' : word) (m' : mem) (o1' o2' o3' o4' o5' : byte),
    ms' = MS (mkR ra' sp gp tp t0' t1' t2' s0' (Z_to_bv 64 0x2c1e68) a0' a1' a2' a3' a4' a5' a6' a7'
                  (Z_to_bv 64 2) (Z_to_bv 64 0x254cb) (Z_to_bv 64 0x22cc50) (Z_to_bv 64 (2^61)) (Z_to_bv 64 0x22dbb0)
                  (Z_to_bv 64 0x213938) (Z_to_bv 64 0x22dbf0) (Z_to_bv 64 0x22db38) (Z_to_bv 64 0x230338) (Z_to_bv 64 0)
                  t3' t4' t5' t6')
             F (Z_to_bv 64 0xafa24) fc None m' (seg_rom asegs)
    /\ munch UNREG_W m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ stk asegs m' XS1_LO XS1_HI /\ stk asegs m' XS2_LO XS2_HI /\ stk asegs m' XS3_LO XS3_HI
    /\ rw_cells asegs m' 0x762a20 [C1 o1'] /\ rw_cells asegs m' 0x7629c0 [C1 o2'] /\ rw_cells asegs m' 0x7629c1 [C1 o3'] /\ rw_cells asegs m' 0x762a21 [C1 o4'] /\ rw_cells asegs m' 0x762a22 [C1 o5'].

Lemma unreg_loop : forall (gs : list gdesc) (K : Z)
    (ra gp tp t0 t1 t2 s0 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word) (sp : word) F fc (m : mem) (o1 o2 o3 o4 o5 : byte),
  Forall (fun g => gd_okb g = true) gs -> Z.of_nat (length gs) = K -> 1 <= K <= 1437 ->
  gds_at m (0x22cc50 - 64 * K) gs ->
  rw_cells asegs m 0x231018 [C1 (Z_to_bv 8 1)] ->
  ro_cells asegs m 0x22fb9c [C1 (Z_to_bv 8 1)] ->
  ro_cells asegs m 0x22db50 [C4 (Z_to_bv 64 1)] ->
  ro_cells asegs m 0x230338 [C8 (Z_to_bv 64 0x7fff8000)] ->
  ro_cells asegs m 0x2c1ee0 [C8 (Z_to_bv 64 0xffffffffffffffff)] ->
  ro_cells asegs m 0x213938 [C8 (Z_to_bv 64 0x203df0)] ->
  stk asegs m XS1_LO XS1_HI -> stk asegs m XS2_LO XS2_HI -> stk asegs m XS3_LO XS3_HI ->
  rw_cells asegs m 0x762a20 [C1 o1] -> rw_cells asegs m 0x7629c0 [C1 o2] -> rw_cells asegs m 0x7629c1 [C1 o3] -> rw_cells asegs m 0x762a21 [C1 o4] -> rw_cells asegs m 0x762a22 [C1 o5] ->
  mem_inv asegs m ->
  evt asegs (unreg_loop_post sp gp tp F fc m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 (Z_to_bv 64 0x2c1e68) a0 a1 a2 a3 a4 a5 a6 a7
             (Z_to_bv 64 2) (Z_to_bv 64 0x254cb) (Z_to_bv 64 (0x22cc50 - 64 * K)) (Z_to_bv 64 (2^61)) (Z_to_bv 64 0x22dbb0)
             (Z_to_bv 64 0x213938) (Z_to_bv 64 0x22dbf0) (Z_to_bv 64 0x22db38) (Z_to_bv 64 0x230338) (Z_to_bv 64 K)
             t3 t4 t5 t6)
        F (Z_to_bv 64 0xaf820) fc None m (seg_rom asegs)).
Proof.
